"""One-time substantive corrections to the submitted report; preserve raw sources."""
from pathlib import Path
R=Path(__file__).resolve().parents[1]; S=R/'05_final_report/sections'
def replace(file,old,new):
    p=S/file; t=p.read_text(encoding='utf-8')
    if old not in t: raise ValueError(f'Missing edit anchor: {file}: {old[:90]}')
    p.write_text(t.replace(old,new),encoding='utf-8')
def para(file,start,new):
    p=S/file; blocks=p.read_text(encoding='utf-8').split('\n\n'); matches=[i for i,b in enumerate(blocks) if b.startswith(start)]
    if len(matches)!=1: raise ValueError((file,start,matches))
    blocks[matches[0]]=new; p.write_text('\n\n'.join(blocks),encoding='utf-8')

